package ru.alfabank.api.accounts.configuration.feign;

import feign.RequestInterceptor;
import feign.RequestTemplate;
import lombok.RequiredArgsConstructor;
import org.springframework.beans.factory.ObjectFactory;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.web.context.request.RequestAttributes;
import org.springframework.web.context.request.RequestContextHolder;
import org.springframework.web.context.request.ServletRequestAttributes;
import ru.alfabank.api.accounts.client.RestServiceHeaders;
import ru.alfabank.api.accounts.configuration.WSProperties;
import ru.alfabank.api.accounts.util.HttpHeaders;

import java.util.Optional;

@RequiredArgsConstructor
public class CommonHeadersFeignInterceptor implements RequestInterceptor {

    @Value("${ws.externalUserCodeValidation.enabled:false}")
    private boolean externalUserCodeValidationEnabled;

    private final ObjectFactory<WSProperties> commonHeadersFeignInterceptor;

    @Override
    public void apply(RequestTemplate requestTemplate) {
        WSProperties properties = commonHeadersFeignInterceptor.getObject();
        String userId = retrieveHeader(HttpHeaders.X_USER_ID)
                .orElseGet(properties::getUserId);
        String branchNumber = retrieveHeader(HttpHeaders.X_BRANCH_NUMBER)
                .orElseGet(properties::getBranchNumber);
        String extSysCode = retrieveHeader(HttpHeaders.X_EXTERNAL_SYSTEM_CODE)
                .orElseGet(properties::getExtSysCode);
        String extUserCode = retrieveHeader(HttpHeaders.X_EXTERNAL_USER_CODE)
                .orElseGet(properties::getExtUserCode);

        if (externalUserCodeValidationEnabled && (extUserCode == null || extUserCode.isBlank())) {
            throw new IllegalArgumentException("X-ExternalUserCode must not be null or empty");
        }

        requestTemplate.header(RestServiceHeaders.X_USER_ID, userId)
                .header(RestServiceHeaders.X_BRANCH_NUMBER, branchNumber)
                .header(RestServiceHeaders.X_EXTERNAL_SYSTEM_CODE, extSysCode)
                .header(RestServiceHeaders.X_EXTERNAL_USER_CODE, extUserCode);
    }

    private Optional<String> retrieveHeader(String headerName) {
        RequestAttributes attributes = RequestContextHolder.currentRequestAttributes();
        return (attributes instanceof ServletRequestAttributes)
                ? Optional.ofNullable(((ServletRequestAttributes) attributes).getRequest().getHeader(headerName))
                : Optional.empty();
    }

}
```

