package ru.alfabank.api.accounts.configuration.feign;

import com.fasterxml.jackson.databind.ObjectMapper;
import feign.codec.ErrorDecoder;
import lombok.RequiredArgsConstructor;
import org.springframework.context.annotation.Bean;
import ru.alfabank.api.accounts.client.exception.UWSDigitalRubleCustomerNotFoundException;
import ru.alfabank.api.accounts.client.exception.UWSDigitalRubleErrorResponse;
import ru.alfabank.api.accounts.client.exception.UWSDigitalRubleServiceException;

import java.io.InputStream;
import java.util.Objects;

import static feign.FeignException.errorStatus;

@RequiredArgsConstructor
public class UWSDigitalRubleClientConfig {
    private static final String CUSTOMER_NOT_FOUND_CODE = "KSM2010";
    private final ObjectMapper objectMapper;

    @Bean
    public ErrorDecoder feignErrorDecoder() {
        return (methodKey, response) -> {
            if (Objects.isNull(response.body())) {
                return errorStatus(methodKey, response);
            }

            try (InputStream inputStream = response.body().asInputStream()) {
                var errorResponse = objectMapper.readValue(inputStream, UWSDigitalRubleErrorResponse.class);

                String code = errorResponse.errorCode();
                String message = errorResponse.errorString();

                if (CUSTOMER_NOT_FOUND_CODE.equals(code)) {
                    return new UWSDigitalRubleCustomerNotFoundException(code, message);
                }

                return new UWSDigitalRubleServiceException(code, message);
            } catch (Exception e) {
                return errorStatus(methodKey, response);
            }
        };
    }
}
